import{_ as a,o as i,c as t,a5 as r}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"Trend viewer","description":"","frontmatter":{},"headers":[],"relativePath":"feature/trend-viewer/spec.md","filePath":"feature/trend-viewer/spec.md"}'),n={name:"feature/trend-viewer/spec.md"};function o(s,e,d,l,c,p){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="trend-viewer" tabindex="-1">Trend viewer <a class="header-anchor" href="#trend-viewer" aria-label="Permalink to &quot;Trend viewer&quot;">​</a></h1><h2 id="objective-and-scope" tabindex="-1">Objective and scope <a class="header-anchor" href="#objective-and-scope" aria-label="Permalink to &quot;Objective and scope&quot;">​</a></h2><p>Admin can inspect published trend snapshots after live crawling or daily S3 replay, without invoking models or graph writes. Reuse the existing AI Redis read APIs. Do not replace another member&#39;s AI Studio/mock screens or modify scoring/publish.</p><h2 id="acceptance-criteria-ui-states" tabindex="-1">Acceptance criteria / UI states <a class="header-anchor" href="#acceptance-criteria-ui-states" aria-label="Permalink to &quot;Acceptance criteria / UI states&quot;">​</a></h2><ul><li>Admin menu and deep link <code>/admin?view=trends</code>; navigation to Neo4j Graph. S3 replay navigation is integrated by the separate replay feature.</li><li>Select live (<code>6h</code>), a historical day (<code>24h</code>) or trailing seven days (<code>7d</code>), target date, and maximum returned candidates (20/50/100). Date is disabled for live.</li><li>Search keyword/related keywords and filter topic locally within the returned bounded result set. Scores remain pipeline values, never labeled percentages.</li><li>Show rank, topic/status, score, component scores, momentum and source post links when present. Disclose detail inline; only http(s) source URLs are clickable.</li><li>Summary describes the latest published snapshot globally, not the selected date&#39;s run or Neo4j health. Missing summary must not hide a successful list.</li><li>Distinguish loading, no published data, no filter matches and request failures; include retry and replay recovery link. No mock fallback, no forced reset.</li><li>Filters use URL query parameters for back/refresh and links from replay days.</li><li>All UI labels under <code>admin.trends</code> and <code>admin.navigation.trends</code> in both <code>src/i18n/locales/{vi,en}/admin.json</code>; preserve BrandHub theme tokens in light/dark, labeled inputs, visible keyboard focus and responsive 375/768/1440 layout.</li></ul><h2 id="api-contract" tabindex="-1">API contract <a class="header-anchor" href="#api-contract" aria-label="Permalink to &quot;API contract&quot;">​</a></h2><ul><li>Existing AI GET <code>/api/v1/ai/trends?period=24h&amp;date=2026-10-08&amp;limit=20</code> (raw array).</li><li>Existing AI GET <code>/api/v1/ai/trends/summary</code> (global latest published status).</li><li>Existing Business GET <code>/api/v1/ai/trending-topics</code> is a mapped current-date view; leave its contract unchanged.</li><li>New Business Admin GET <code>/api/v1/admin/ai/trends</code> accepts <code>period</code>, optional ISO <code>date</code>, <code>limit</code> and returns the unchanged candidate array in ApiResponse.</li><li>New Admin GET <code>/api/v1/admin/ai/trends/summary</code> returns AI summary in ApiResponse.</li><li>Every new endpoint requires an active Admin before upstream reads; validate period/date/limit. Errors remain structured; no AI internal key in browser.</li></ul><h2 id="out-of-scope-definition-of-done" tabindex="-1">Out of scope / definition of done <a class="header-anchor" href="#out-of-scope-definition-of-done" aria-label="Permalink to &quot;Out of scope / definition of done&quot;">​</a></h2><p>The current viewer also exposes the existing guarded crawl APIs through a confirmation action and crawl-history drawer. Its frontend dependencies are CrawlRunsDrawer and crawlConfigService; no crawler/pipeline backend is introduced by this change. New labels use admin.crawlRuns/admin.crawl/admin.trendVisuals in the parallel vi/en Admin locale files. S3 replay implementation is committed separately from this viewer/graph scope.</p><p>No migration, seed, deletion, background crawl/replay execution, AI generation, new DB storage, charts inventing missing history, commit or push. Done when Java compile/local isolated checks and frontend build/lint/browser cases pass. Real published data may remain absent until the blocked replay successfully resumes.</p>',10)])])}const m=a(n,[["render",o]]);export{h as __pageData,m as default};
